      "id": 3,
      "claim": "The hepatopancreatic ampulla opens into the second part of the duodenum at the major duodenal papilla.",
      "evidence": "Standard anatomical landmark: The ampulla of Vater is located in the medial wall of the descending duodenum (D2).",
      "weight": 0.35,
      "depends_on": [2]
    },
